t.script:
document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('pretest_form');
    if (!form) { return; }
    var attemptId = form.dataset.attemptId;
    var remaining = parseInt(form.dataset.remaining, 10);

    var cards = Array.prototype.slice.call(document.querySelectorAll('.ps-question'));
    cards.sort(function (a, b) {
        return parseInt(a.dataset.index, 10) - parseInt(b.dataset.index, 10);
    });
    var total = cards.length;
    var current = 0;

    var elPrev = document.getElementById('ps_prev');
    var elNext = document.getElementById('ps_next');
    var elFinish = document.getElementById('ps_finish');
    var elCurrent = document.getElementById('ps_current');
    var elProgress = document.getElementById('ps_progress');
    var elAnswered = document.getElementById('ps_answered');

    function countAnswered() {
        var n = 0;
        cards.forEach(function (card) {
            var checked = card.querySelector('input[type=radio]:checked');
            var essay = card.querySelector('textarea');
            if (checked) { n++; }
            else if (essay && essay.value.trim() !== '') { n++; }
        });
        return n;
    }

    function render() {
        cards.forEach(function (card, i) {
            card.classList.toggle('active', i === current);
        });
        if (elCurrent) { elCurrent.textContent = current + 1; }
        if (elProgress) { elProgress.style.width = ((current + 1) / total * 100) + '%'; }
        elPrev.disabled = (current === 0);
        var isLast = (current === total - 1);
        elNext.classList.toggle('d-none', isLast);
        elFinish.classList.toggle('d-none', !isLast);
    }

    elPrev.addEventListener('click', function () {
        if (current > 0) { current--; render(); window.scrollTo(0, 0); }
    });
    elNext.addEventListener('click', function () {
        if (current < total - 1) { current++; render(); window.scrollTo(0, 0); }
    });

    // ---- Submit manual ----
    var submitting = false;
    function doSubmit() {
        if (submitting) { return; }
        submitting = true;
        form.submit();
    }
    elFinish.addEventListener('click', function () {
        if (elAnswered) { elAnswered.textContent = countAnswered(); }
        document.getElementById('ps_confirm_overlay').style.display = 'flex';
    });
    document.getElementById('ps_cancel_submit').addEventListener('click', function () {
        document.getElementById('ps_confirm_overlay').style.display = 'none';
    });
    document.getElementById('ps_confirm_submit').addEventListener('click', doSubmit);

    // ---- Highlight + autosave pilihan ganda ----
    document.querySelectorAll('.ps-mc').forEach(function (radio) {
        radio.addEventListener('change', function () {
            var name = this.name;
            document.querySelectorAll('input[name="' + name + '"]').forEach(function (r) {
                r.closest('.answer-option').classList.remove('selected');
            });
            this.closest('.answer-option').classList.add('selected');
            var qid = name.replace('answer_', '');
            saveAnswer({ question_id: parseInt(qid, 10), answer_id: parseInt(this.value, 10) });
        });
    });

    // ---- Autosave esai (debounce) ----
    document.querySelectorAll('.ps-essay').forEach(function (ta) {
        var t;
        ta.addEventListener('input', function () {
            clearTimeout(t);
            var el = this;
            t = setTimeout(function () {
                saveAnswer({ question_id: parseInt(el.dataset.qid, 10), essay_text: el.value });
            }, 700);
        });
    });

    function saveAnswer(params) {
        fetch('/pslearning/pretest/' + attemptId + '/save', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: params })
        }).then(function (r) { return r.json(); })
          .then(function (res) {
              var d = (res && res.result) || {};
              if (d.expired) { triggerTimeUp(); }
          }).catch(function () { /* diam saja, autosave bersifat best-effort */ });
    }

    // ---- Countdown timer ----
    function triggerTimeUp() {
        document.getElementById('ps_timeup').style.display = 'flex';
        form.querySelectorAll('input, textarea, button').forEach(function (el) {
            if (el.type !== 'hidden') { el.disabled = true; }
        });
        setTimeout(doSubmit, 800);
    }

    if (remaining >= 0) {
        var timerEl = document.getElementById('ps_timer');
        var timerText = document.getElementById('ps_timer_text');
        function tick() {
            if (remaining <= 0) {
                timerText.textContent = '00:00';
                triggerTimeUp();
                return;
            }
            var m = Math.floor(remaining / 60);
            var s = remaining % 60;
            timerText.textContent = (m < 10 ? '0' : '') + m + ':' + (s < 10 ? '0' : '') + s;
            timerEl.classList.toggle('warning', remaining <= 120 && remaining > 60);
            timerEl.classList.toggle('danger', remaining <= 60);
            remaining--;
            setTimeout(tick, 1000);
        }
        tick();
    }

    render();
});

document.addEventListener('DOMContentLoaded', function () {
    var root = document.getElementById('ps_learn_root');
    if (!root) { return; }
    var enrollmentId = root.dataset.enrollmentId;

    document.querySelectorAll('.ps-toggle').forEach(function (btn) {
        btn.addEventListener('click', function () {
            var matId = parseInt(this.dataset.materialId, 10);
            var newDone = this.dataset.done !== '1';
            var self = this;
            self.disabled = true;
            fetch('/pslearning/learn/' + enrollmentId + '/toggle', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ jsonrpc: '2.0', method: 'call',
                    params: { material_id: matId, done: newDone } })
            }).then(function (r) { return r.json(); })
              .then(function (res) {
                  var d = (res && res.result) ? res.result : {};
                  if (!d.ok) { self.disabled = false; return; }
                  // Reload agar status kunci materi berikutnya ikut diperbarui
                  window.location.reload();
              }).catch(function () { self.disabled = false; });
        });
    });
});
